var BASE_URL = API_CONFIG.LAPRAS_BASE_URL;
var ApiClient = class {
  baseUrl;
  getHeaders;
  timeout;
  constructor(options) {
    this.baseUrl = options.baseUrl;
    this.getHeaders = options.headers || (() => ({}));
    this.timeout = options.timeout || 3e4;
  }
  /**
   * タイムアウト付きfetchラッパー
   */
  async fetchWithTimeout(url2, options) {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), this.timeout);
    try {
      const response = await fetch(url2, {
        ...options,
        signal: options.signal || controller.signal
      });
      clearTimeout(timeoutId);
      return response;
    } catch (error45) {
      clearTimeout(timeoutId);
      throw error45;
    }
  }
  /**
   * レスポンス処理
   */
  async handleResponse(response) {
    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`API Error (${response.status}): ${errorText}`);
    }
    const contentType = response.headers.get("content-type");
    if (contentType?.includes("application/json")) {
      return response.json();
    }
    return response.text();
  }
  /**
   * GETリクエスト
   */
  async get(path, options) {
    return this.request(path, { ...options, method: "GET" });
  }
  /**
   * POSTリクエスト
   */
  async post(path, body, options) {
    return this.request(path, { ...options, method: "POST", body });
  }
  /**
   * PUTリクエスト
   */
  async put(path, body, options) {
    return this.request(path, { ...options, method: "PUT", body });
  }
  /**
   * DELETEリクエスト
   */
  async delete(path, options) {
    return this.request(path, { ...options, method: "DELETE" });
  }
  /**
   * 汎用リクエストメソッド
   */
  async request(path, options = {}) {
    const pathWithSource = path.includes("?") ? `${path}&${API_CONFIG.SOURCE_QUERY.substring(1)}` : `${path}${API_CONFIG.SOURCE_QUERY}`;
    const url2 = `${this.baseUrl}${pathWithSource}`;
    const headers = {
      ...this.getHeaders(),
      ...options.headers
    };
    const fetchOptions = {
      method: options.method || "GET",
      headers
    };
    if (options.body !== void 0) {
      fetchOptions.body = JSON.stringify(options.body);
    }
    const response = await this.fetchWithTimeout(url2, fetchOptions);
    return this.handleResponse(response);
  }
};
var laprasApiClient = new ApiClient({
  baseUrl: BASE_URL,
  headers: () => {
    const apiKey = getEnvironmentVariable("LAPRAS_API_KEY");
    if (!apiKey) {
      throw new Error("LAPRAS_API_KEY is not set in environment variables");
    }
    return {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json"
    };
  },
  timeout: 3e4
});
var getCurrentLaprasState = async () => {
  const [experiences, jobSummary, wantToDo] = await Promise.all([
    laprasApiClient.get("/experiences"),
    laprasApiClient.get("/job_summary"),
    laprasApiClient.get("/want_to_do")
  ]);
  return {
    ...experiences,
    ...jobSummary,
    ...wantToDo
  };
};
var createExperience = async (params) => {
  return laprasApiClient.post("/experiences", params);
};
var deleteExperience = async (experienceId) => {
  await laprasApiClient.delete(`/experiences/${experienceId}`);
};
var deleteAllExperiences = async () => {
  const state = await getCurrentLaprasState();
  const deletePromises = state.experience_list.map((exp) => deleteExperience(exp.id));
  await Promise.all(deletePromises);
};
var updateJobSummary = async (jobSummary) => {
  await laprasApiClient.put("/job_summary", jobSummary);
};
var updateWantToDo = async (wantToDo) => {
  await laprasApiClient.put("/want_to_do", wantToDo);
};
var restoreLaprasState = async (state) => {
  await deleteAllExperiences();
  for (const exp of state.experience_list) {
    const params = {
      organization_name: exp.organization_name,
      positions: exp.positions.map((p) => ({ id: p.id })),
      position_name: exp.position_name,
      start_year: exp.start_year,
      start_month: exp.start_month,
      end_year: exp.end_year ?? 0,
      end_month: exp.end_month ?? 0,
      is_client_work: exp.is_client_work,
      client_company_name: exp.client_company_name ?? void 0,
      description: exp.description
    };
    await createExperience(params);
  }
  await Promise.all([
    updateJobSummary({ job_summary: state.job_summary }),
    updateWantToDo({ want_to_do: state.want_to_do })
  ]);
};

