// src/mastra/workflows/utils/formatState.ts
init_cjs_shims();
function formatState(state) {
  const experiences = state.experience_list.map((exp) => {
    const endDate = exp.end_year ? `${exp.end_year}/${exp.end_month || ""}` : "\u73FE\u5728";
    const period = `${exp.start_year}/${exp.start_month} - ${endDate}`;
    const clientInfo = exp.is_client_work && exp.client_company_name ? `
**\u30AF\u30E9\u30A4\u30A2\u30F3\u30C8:** ${exp.client_company_name}` : "";
    const positionsList = exp.positions && exp.positions.length > 0 ? exp.positions.map((pos) => `  - ${pos.job_position_name}`).join("\n") : null;
    const descriptionFormatted = exp.description.split(/。/).filter((line) => line.trim()).map((line) => `- ${line.trim()}\u3002`).join("\n");
    return `### ${exp.organization_name}
**\u671F\u9593:** ${period}  
${positionsList ? `
**\u8077\u7A2E:**
${positionsList}
` : ""}
**\u5F79\u5272\u30FB\u5F79\u8077:** ${exp.position_name}${clientInfo}
**\u30D7\u30ED\u30B8\u30A7\u30AF\u30C8\u30FB\u696D\u52D9\u5185\u5BB9:**
${descriptionFormatted}`;
  }).join("\n\n---\n\n");
  return `# LAPRAS Career State

## \u4ECA\u5F8C\u306E\u30AD\u30E3\u30EA\u30A2\u3067\u3084\u308A\u305F\u3044\u3053\u3068
${state.want_to_do}

## \u8077\u52D9\u8981\u7D04
${state.job_summary}

## \u8077\u6B74
${experiences}
`;
}

